def transform(grid):
    # Based on analysis of Demo 7 and other demographics:
    # Isolated pixels of certain colors change
    # From Demo 7: an isolated 0 became a 2
    # Hypothesis: swap 0 and 2 for isolated pixels

    output = []
    for r, row in enumerate(grid):
        new_row = []
        for c, cell in enumerate(row):
            if cell == 0:
                # Isolated 0s become 2s
                # Check if adjacent 0s
                is_isolated = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == 0:
                                is_isolated = False
                                break
                    if not is_isolated: break
                new_row.append(2 if is_isolated else 0)
            elif cell == 2:
                # Isolated 2s become 0s
                is_isolated = True
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == 2:
                                is_isolated = False
                                break
                    if not is_isolated: break
                new_row.append(0 if is_isolated else 2)
            else:
                new_row.append(cell)
        output.append(new_row)
    return output
